const cfg = $('Settings').first().json;

// single-item input: one booking, or one form submission. Both triggers hand
// this node exactly one item, and a second booking is a second execution.
const src = $input.first().json || {};

// Calendly nests everything under `payload`; the form puts the fields at the
// top level. Reading both here keeps every node downstream trigger-agnostic.
const cal = src.payload || (src.body && src.body.payload) || null;

let person = '', email = '', company = '', when = '', notes = '', topic = '';

if (cal) {
  person = String(cal.name || '').trim();
  email = String(cal.email || '').trim();
  const ev = cal.scheduled_event || {};
  topic = String(ev.name || '').trim();
  when = String(ev.start_time || '').trim();
  const qa = Array.isArray(cal.questions_and_answers) ? cal.questions_and_answers : [];
  notes = qa.map((q) => (q.question || '') + ': ' + (q.answer || '')).join(' | ');
  // Calendly asks for the company on a lot of booking forms; use it if it is there.
  const cq = qa.find((q) => /company|organi[sz]ation|business/i.test(q.question || ''));
  if (cq) company = String(cq.answer || '').trim();
} else {
  person = String(src['Full name'] || '').trim();
  email = String(src['Work email'] || '').trim();
  company = String(src['Company'] || '').trim();
  topic = String(src['What is the meeting about'] || '').trim();
  notes = topic;
}

// A personal address tells you nothing about a company, and researching
// "Gmail" is worse than admitting there is nothing to research.
const FREE_MAIL = [
  'gmail.com','googlemail.com','outlook.com','hotmail.com','live.com','msn.com',
  'yahoo.com','ymail.com','icloud.com','me.com','mac.com','proton.me',
  'protonmail.com','aol.com','gmx.com','mail.com','zoho.com','yandex.com','qq.com'
];

const at = email.indexOf('@');
let domain = at > -1 ? email.slice(at + 1).toLowerCase().trim() : '';
if (FREE_MAIL.indexOf(domain) !== -1) domain = '';

// Fall back to the brand in the domain when nobody typed a company name.
if (!company && domain) {
  const brand = domain.split('.')[0].replace(/-/g, ' ');
  company = brand.charAt(0).toUpperCase() + brand.slice(1);
}

return [{ json: {
  person: person || '(name not given)',
  email: email,
  domain: domain,
  company: company,
  topic: topic,
  when: when,
  notes: notes.slice(0, 500),
  researchable: !!(domain || company)
} }];

const b = $('Read The Booking').first().json;

// single-item input: one search, one response. The results are inside it.
let body = $input.first().json;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
if (typeof body.body === 'string') { try { body = JSON.parse(body.body); } catch (e) { /* keep */ } }

const rows = Array.isArray(body && body.organic) ? body.organic : [];
const hit = rows.find((r) => /linkedin\.com\/company\//i.test(String(r.link || '')));

// Google answers with whichever country subdomain it feels like - il., uk., de.
// The dataset wants the canonical host, so the country prefix is stripped.
let url = '';
if (hit) {
  url = String(hit.link)
    .replace(/^https?:\/\/[a-z]{2,3}\.linkedin\.com/i, 'https://www.linkedin.com')
    .replace(/^http:/, 'https:')
    .split('?')[0]
    .replace(/\/$/, '');
}

// Always one item, even with nothing found. The fetch below then runs on an
// empty URL, Bright Data answers with an error body, and the evidence step
// reports "no LinkedIn page found" - which is the truth, and keeps the Merge
// fed. Returning zero items here would strand the whole branch.
return [{ json: Object.assign({}, b, { linkedin_url: url }) }];

const b = $('Read The Booking').first().json;
const picked = $('Pick The Company Page').first().json || {};

// single-item input: one company, one record.
let payload = $input.first().json;
if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch (e) { payload = {}; } }

let rec = null;
if (Array.isArray(payload)) rec = payload[0];
else if (payload && payload.name) rec = payload;
else if (payload && Array.isArray(payload.data)) rec = payload.data[0];

// Bright Data answers a bad request with HTTP 200 and an error body, which
// neverError hands straight through as if it were data.
const failed = !rec || !rec.name || !!(payload && payload.error);

function clip(s, n) {
  return String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);
}

return [{ json: {
  kind: 'linkedin',
  found: !failed,
  url: picked.linkedin_url || '',
  name: failed ? '' : clip(rec.name, 120),
  about: failed ? '' : clip(rec.about || rec.description, 700),
  industry: failed ? '' : clip(rec.industries, 120),
  size: failed ? '' : clip(rec.company_size, 60),
  staff_on_linkedin: failed ? '' : String(rec.employees_in_linkedin || ''),
  hq: failed ? '' : clip(rec.headquarters, 120),
  founded: failed ? '' : String(rec.founded || ''),
  followers: failed ? '' : String(rec.followers || ''),
  specialties: failed ? '' : clip(rec.specialties, 400),
  real_website: failed ? '' : clip(rec.website, 160)
} }];

const b = $('Read The Booking').first().json;

// single-item input: one homepage, one response.
let payload = $input.first().json;
const md = typeof payload === 'string'
  ? payload
  : String(payload.data ?? payload.body ?? '');

// The markdown converter keeps the words and drops the markup, which is exactly
// what a positioning read wants - and about 13x less of it than raw HTML.
const text = md
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  .replace(/[#*_>`|-]{2,}/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{ json: {
  kind: 'site',
  found: text.length > 200,
  domain: b.domain,
  // The top of a homepage is the pitch. Past a couple of thousand characters it
  // is navigation, cookie notices and footer links, which teach the model
  // nothing and cost tokens.
  pitch: text.slice(0, 1800)
} }];

const cfg = $('Settings').first().json;
const b = $('Read The Booking').first().json;

// single-item input: one search, one response.
let body = $input.first().json;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
if (typeof body.body === 'string') { try { body = JSON.parse(body.body); } catch (e) { /* keep */ } }

if (body && body.error) {
  return [{ json: { kind: 'news', found: false, items: [],
    note: 'Search failed: ' + String(body.error).slice(0, 120) } }];
}

const rows = Array.isArray(body && body.news) ? body.news
           : (Array.isArray(body && body.organic) ? body.organic : []);

// A company name is a common word often enough that an unfiltered sweep returns
// somebody else's press release. Requiring the name as a whole word in the
// headline is a cheap way to keep the brief about the right company.
const named = new RegExp('\\b' + String(b.company || '').replace(/[^A-Za-z0-9 ]+/g, ' ').trim() + '\\b', 'i');

const items = [];
for (const r of rows) {
  const title = String(r.title || '');
  if (!title || !named.test(title)) continue;
  items.push({
    title: title.slice(0, 180),
    source: String(r.source || r.display_link || '').slice(0, 60),
    when: String(r.date || ''),
    link: String(r.link || '')
  });
  if (items.length >= Math.max(1, Number(cfg.headlines_to_keep) || 5)) break;
}

return [{ json: { kind: 'news', found: items.length > 0, items: items } }];

const b = $('Read The Booking').first().json;

// All three branches come out of the Merge together. Reading them from this
// node's own input rather than by node name means a branch that returned
// nothing useful cannot throw - it simply is not in the pile.
const by = { linkedin: null, site: null, news: null };
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.kind && by.hasOwnProperty(j.kind)) by[j.kind] = j;
}

const li = by.linkedin || {};
const site = by.site || {};
const news = by.news || {};

const lines = [];
lines.push('MEETING');
lines.push('  with: ' + b.person + (b.email ? ' <' + b.email + '>' : ''));
lines.push('  company: ' + (b.company || 'unknown') + (b.domain ? ' (' + b.domain + ')' : ''));
if (b.topic) lines.push('  booked for: ' + b.topic);
if (b.when) lines.push('  starts: ' + b.when);
if (b.notes) lines.push('  they wrote: ' + b.notes);
lines.push('');

if (li.found) {
  lines.push('LINKEDIN COMPANY RECORD');
  if (li.about) lines.push('  about: ' + li.about);
  if (li.industry) lines.push('  industry: ' + li.industry);
  if (li.size) lines.push('  size: ' + li.size + (li.staff_on_linkedin ? ' (' + li.staff_on_linkedin + ' on LinkedIn)' : ''));
  if (li.hq) lines.push('  headquarters: ' + li.hq);
  if (li.founded) lines.push('  founded: ' + li.founded);
  if (li.specialties) lines.push('  specialties: ' + li.specialties);
  lines.push('');
} else {
  lines.push('LINKEDIN COMPANY RECORD: none found');
  lines.push('');
}

if (site.found) {
  lines.push('HOW THEY DESCRIBE THEMSELVES (their homepage)');
  lines.push('  ' + site.pitch);
  lines.push('');
} else {
  lines.push('HOMEPAGE: could not be read');
  lines.push('');
}

if (news.found) {
  lines.push('RECENT NEWS');
  for (const n of news.items) lines.push('  [' + n.when + '] ' + n.title + ' (' + n.source + ')');
} else {
  lines.push('RECENT NEWS: nothing found in the window searched');
}

return [{ json: {
  person: b.person,
  company: b.company,
  domain: b.domain,
  topic: b.topic,
  when: b.when,
  linkedin_url: li.url || '',
  sources: {
    linkedin: !!li.found,
    site: !!site.found,
    news: news.found ? news.items.length : 0
  },
  news_items: news.items || [],
  evidence: lines.join('\n')
} }];

const cfg = $('Settings').first().json;
const e = $('Build The Evidence').first().json;

// single-item input: one booking produced one evidence block, so the chain
// above returned one brief.
const raw = $input.first().json;
let brief = String(raw.text || raw.output || raw.response || '').trim();

// Slack is not markdown. `**bold**` renders with the asterisks showing, and the
// model reaches for it however the prompt is worded, so it is corrected here
// rather than argued about in the prompt.
brief = brief.replace(/\*\*([^*\n]+)\*\*/g, '*$1*');

// An ISO timestamp is not a time anybody reads before a call.
function when(iso) {
  const t = Date.parse(iso || '');
  if (isNaN(t)) return String(iso || '');
  const d = new Date(t);
  const day = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d.getUTCDay()];
  const mon = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getUTCMonth()];
  const hh = String(d.getUTCHours()).padStart(2, '0');
  const mm = String(d.getUTCMinutes()).padStart(2, '0');
  return `${day} ${d.getUTCDate()} ${mon}, ${hh}:${mm} UTC`;
}

const src = [];
if (e.sources.linkedin) src.push('LinkedIn');
if (e.sources.site) src.push('their site');
if (e.sources.news) src.push(e.sources.news + ' news item' + (e.sources.news === 1 ? '' : 's'));

const head = [];
head.push('*Pre-call brief - ' + e.person + (e.company ? ' at ' + e.company : '') + '*');
if (e.when) head.push('Starts ' + when(e.when) + (e.topic ? '  ·  ' + e.topic : ''));
else if (e.topic) head.push(e.topic);
head.push('');

const foot = [];
foot.push('');
// Say what the brief is built on. A brief with one weak source should be read
// differently from one with three, and only this node knows which it was.
foot.push('_Built from: ' + (src.length ? src.join(', ') : 'nothing - all three lookups came back empty') + '._');
if (e.linkedin_url) foot.push('_' + e.linkedin_url + '_');
for (const n of (e.news_items || []).slice(0, 3)) {
  if (n.link) foot.push('_' + n.title.slice(0, 90) + ' - ' + n.link + '_');
}

return [{ json: {
  person: e.person,
  company: e.company,
  message: head.join('\n') + (brief || '_The model returned nothing. The evidence is below._\n\n' + e.evidence) + foot.join('\n')
} }];
